// Get the video ID and resolution from the visual analysis form
const form = $('Visual analysis form').first().json;
const raw = String(form['YouTube URL'] || '').trim();

const patterns = [
  /(?:[?&]v=|\/live\/|\/shorts\/|\/embed\/|youtu\.be\/)([A-Za-z0-9_-]{11})/,
  /^([A-Za-z0-9_-]{11})$/,
];
let videoId = null;
for (const p of patterns) {
  const m = raw.match(p);
  if (m) { videoId = m[1]; break; }
}
if (!videoId) throw new Error('Could not find a video ID in the URL: ' + raw);

const resolution = String(form['Resolution'] || '').startsWith('Low')
  ? 'MEDIA_RESOLUTION_LOW'
  : 'MEDIA_RESOLUTION_HIGH';

return [{ json: { video_id: videoId, resolution } }];

// Split the video into 10-minute chunks and build a Gemini request for each
const CHUNK_SECONDS = 600;  // length of each chunk. Lower it if Gemini reports MAX_TOKENS.
const FPS = 1;              // frames per second Gemini watches

const input = $('Prepare analysis').first().json;
const row = $input.first().json;
if (!row || !row.video_id) {
  throw new Error(`Video ${input.video_id} is not in the livestreams table yet. Ingest it with workflow 1 first.`);
}
const total = Number(row.duration_seconds);
if (!total || total <= 0) throw new Error('Unknown video duration (duration_seconds is empty).');

const url = `https://www.youtube.com/watch?v=${row.video_id}`;

const schema = {
  type: 'object',
  properties: {
    scenes: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          start_sec: { type: 'integer' },
          end_sec: { type: 'integer' },
          description: { type: 'string' },
          on_screen_text: { type: 'string' },
          keywords: { type: 'array', items: { type: 'string' } },
        },
        required: ['start_sec', 'end_sec', 'description', 'on_screen_text', 'keywords'],
      },
    },
    links: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          at_sec: { type: 'integer' },
          url: { type: 'string' },
          source: { type: 'string', enum: ['screen', 'speech'] },
          context: { type: 'string' },
        },
        required: ['at_sec', 'url', 'source', 'context'],
      },
    },
  },
  required: ['scenes', 'links'],
};

const prompt = (length) => `You are watching ONE CHUNK, ${length} seconds long, of the livestream "${row.title || ''}".
Task: write a detailed visual log so that questions like "when does the red shirt appear", "when does the pricing slide show up" or "which links did she open" can be answered later.

TIME: every timestamp is the NUMBER OF SECONDS FROM THE START OF THIS CHUNK (start of chunk = 0, end of chunk = ${length}).

1) scenes: split the chunk into consecutive scenes that cover 0 to ${length} without gaps.
   Start a new scene on every visible change: slide change, a web page opened or switched, a product picked up or put down, a change of clothes, a new person, a camera angle change, screen sharing starting or stopping.
   Merge long static stretches into one scene, but no scene may be longer than 60 seconds.
   - description: in Vietnamese, specific: who (gender, appearance), clothing WITH COLOURS, objects/products with colours, actions, surroundings, what the shared screen shows.
   - on_screen_text: copy legible text verbatim (slide titles, prices, discount codes, product names, URL in the address bar). Empty string if none.
   - keywords: 3–10 short phrases in Vietnamese, e.g. the Vietnamese words for "red shirt", "price list", "slide", "browser", "phone".

2) links: every link, URL or domain name:
   - source "screen": seen in the browser address bar, on a slide, in an image, in a pinned comment... Add one entry each time a NEW web page is opened or navigated to.
   - source "speech": the speaker reads out a link or domain name.
   - url: copy exactly as seen/heard; if it is not fully legible, write the legible part (e.g. the domain).
   - context: what the page is and why it was opened.

Only record what is actually seen or heard. Do not guess, do not make things up.`;

const items = [];
for (let start = 0, chunk = 1; start < total; start += CHUNK_SECONDS, chunk++) {
  const end = Math.min(start + CHUNK_SECONDS, total);
  items.push({
    json: {
      video_id: row.video_id,
      chunk,
      start_sec: start,
      end_sec: end,
      body: {
        contents: [{
          role: 'user',
          parts: [
            {
              fileData: { fileUri: url },
              videoMetadata: { startOffset: `${start}s`, endOffset: `${end}s`, fps: FPS },
            },
            { text: prompt(end - start) },
          ],
        }],
        generationConfig: {
          mediaResolution: input.resolution,
          responseMimeType: 'application/json',
          responseJsonSchema: schema,
          thinkingConfig: { thinkingLevel: 'LOW' },
          maxOutputTokens: 32768,
        },
      },
    },
  });
}
return items;

// Merge the results of all chunks and convert chunk-relative seconds to video time
const chunks = $('Split into 10-minute chunks').all();
const outs = $input.all();

const scenes = [];
const links = [];
let totalTokens = 0;

const toInt = (v) => {
  const n = Math.round(Number(v));
  return Number.isFinite(n) ? n : null;
};

chunks.forEach((c, i) => {
  const { chunk, start_sec: start, end_sec: end } = c.json;
  const res = outs[i]?.json || {};
  if (res.error) throw new Error(`Chunk ${chunk}: Gemini error: ${JSON.stringify(res.error).slice(0, 300)}`);

  const cand = (res.candidates || [])[0];
  // Skip "thought" parts, otherwise JSON.parse fails
  const text = ((cand && cand.content && cand.content.parts) || [])
    .filter((p) => !p.thought && typeof p.text === 'string')
    .map((p) => p.text)
    .join('');
  if (!text) {
    throw new Error(`Chunk ${chunk}: Gemini returned nothing (finishReason=${cand?.finishReason}, ${JSON.stringify(res.promptFeedback || {})}). The video must be public.`);
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    throw new Error(`Chunk ${chunk}: invalid JSON (finishReason=${cand?.finishReason}). If it is MAX_TOKENS, lower CHUNK_SECONDS in the "Split into 10-minute chunks" node.`);
  }
  totalTokens += Number(res.usageMetadata?.totalTokenCount) || 0;

  const rawScenes = Array.isArray(data.scenes) ? data.scenes : [];
  const rawLinks = Array.isArray(data.links) ? data.links : [];

  // The prompt asks for chunk-relative times; if the model used video time anyway, don't add the offset
  const length = end - start;
  const stamps = [
    ...rawScenes.flatMap((s) => [toInt(s.start_sec), toInt(s.end_sec)]),
    ...rawLinks.map((l) => toInt(l.at_sec)),
  ].filter((v) => v !== null);
  let offset = start;
  if (start > 0 && stamps.length && Math.max(...stamps) > length + 5 && Math.min(...stamps) >= start - 5) offset = 0;
  const convert = (v) => Math.min(end, Math.max(start, (toInt(v) ?? 0) + offset));

  for (const s of rawScenes) {
    const description = String(s.description || '').trim();
    if (!description) continue;
    const a = convert(s.start_sec);
    const b = Math.max(a, convert(s.end_sec));
    scenes.push({
      start_sec: a,
      end_sec: b,
      description,
      on_screen_text: String(s.on_screen_text || '').trim(),
      keywords: (Array.isArray(s.keywords) ? s.keywords : [s.keywords])
        .map((x) => String(x || '').trim()).filter(Boolean).join(', '),
    });
  }
  for (const l of rawLinks) {
    const u = String(l.url || '').trim();
    if (!u) continue;
    links.push({
      at_sec: convert(l.at_sec),
      url: u,
      source: l.source === 'speech' ? 'speech' : 'screen',
      context: String(l.context || '').trim(),
    });
  }
});

scenes.sort((a, b) => a.start_sec - b.start_sec);
links.sort((a, b) => a.at_sec - b.at_sec);

return [{
  json: {
    video_id: chunks[0].json.video_id,
    chunk_count: chunks.length,
    scene_count: scenes.length,
    link_count: links.length,
    total_tokens: totalTokens,
    scenes: JSON.stringify(scenes),
    links: JSON.stringify(links),
  },
}];
